"""Fresh P1 double replay, actual regression/boundary checks and owner-review seal."""
import importlib.util,json,re,subprocess,sys,os
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('p1build',ROOT/'scripts/build-dfr05-p1.py');c=importlib.util.module_from_spec(spec);spec.loader.exec_module(c)
NODE=os.environ.get('DFR05_NODE_BINARY','node')
def execute(args):
 r=subprocess.run(args,cwd=ROOT,capture_output=True,text=True)
 if r.returncode:raise RuntimeError('FAILED: '+' '.join(args)+'\n'+r.stdout+r.stderr)
 found=re.search(r'Ran (\d+) tests',r.stderr)
 return dict(command=' '.join(args),exitCode=r.returncode,tests=int(found.group(1)) if found else None,stdout=r.stdout,stderr=r.stderr)
def main():
 runtime=execute([NODE,'--version']);version=re.fullmatch(r'v(\d+)\.(\d+)\.(\d+)',runtime['stdout'].strip())
 if not version or not (22,23,2)<=tuple(map(int,version.groups()))<(23,0,0):raise ValueError('SUPPORTED_NODE_REQUIRED: >=22.23.2 <23; configure PATH or DFR05_NODE_BINARY. No runtime is downloaded.')
 # Both runs use exactly the same code; volatile authorization-record time is outside core payload.
 c.build();one=c.load(c.REL+'/pipeline-summary.json')['deterministicPayloadHash']
 c.build();two=c.load(c.REL+'/pipeline-summary.json')['deterministicPayloadHash']
 if one!=two:raise ValueError('NONDETERMINISTIC_REPLAY')
 c.dump('determinism-results.json',dict(status='PASS',independentPipelineExecutions=2,firstPayloadHash=one,secondPayloadHash=two,excludes='Owner authorization record timestamp and execution receipts; metrics, source projection, graph and qualification replay are included.'))
 runs=[execute([sys.executable,'scripts/test-dfr05-p1.py']),execute([sys.executable,'scripts/test-dfr02.py']),execute([sys.executable,'scripts/test-dfr04-closure.py']),execute([NODE,'scripts/verify-dfr05-p1-boundaries.mjs']),execute([NODE,'scripts/verify-approved-scoring-authority.mjs'])]
 snapshot=c.load(c.REL+'/baseline-snapshot.json');c.check(snapshot['protectedFiles'])
 from lib.dfr05_p1 import Store,validate_dossier
 Store(expected=c.load(c.REL+'/input-pins.json')).validate()
 for p,h in c.load(c.REL+'/implementation-pins.json').items():
  if c.sha(ROOT/p)!=h:raise ValueError('IMPLEMENTATION_CHANGED:'+p)
 summary=c.load(c.REL+'/pipeline-summary.json');parity=c.load(c.REL+'/parity-results.json');boundary=c.load(c.REL+'/boundary-results.json')
 if boundary['probes']!=54 or any(r['status']!='REJECTED' for r in boundary['records']):raise ValueError('BOUNDARY_FAILURE')
 for t in c.PILOT:validate_dossier(c.load(c.REL+f'/issuers/{t}.json'),c.load(c.D4+f'/issuers/{t}.json'))
 results=dict(status='PASS',validatedAt=datetime.now(timezone.utc).isoformat(),baselineCommit=c.BASELINE,actualRuns=runs,nodeRuntime=runtime,protectedFilesVerified=len(snapshot['protectedFiles']),protectedAndDatabaseBytesUnchanged=True,financialParity=parity,deterministicCorePayload=True,productionBoundaryRejections=54,completedUnchanged=25,deferredUnchanged=113,newAssessments=0,p2Started=False,newExternalSources=0,productionActivated=False,ownerP1Approval='EXPLICIT_OWNER_CONVERSATION_MESSAGE_RECORDED',ownerP1ResultAcceptance='PENDING',independentHumanReviewClaimed=False,scope='P1 six-pilot foundation validation only; not whole-application release acceptance.')
 c.dump('validation-results.json',results)
 reports(summary,results,runs)
 files={str(p.relative_to(c.OUT)):c.sha(p) for p in sorted(c.OUT.rglob('*')) if p.is_file() and p.name!='manifest.json'}
 c.dump('manifest.json',dict(contract='dfr05-p1-owner-review-candidate-v1',baselineCommit=c.BASELINE,status='PENDING_OWNER_REVIEW',files=files,implementation=c.load(c.REL+'/implementation-pins.json'),sourcePinsHash=c.sha(c.OUT/'input-pins.json'),baselineSnapshotHash=c.sha(c.OUT/'baseline-snapshot.json'),p2Authorized=False,productionActivated=False))
 manifest=c.load(c.REL+'/manifest.json')
 for p,h in manifest['files'].items():
  if c.sha(c.OUT/p)!=h:raise ValueError('OUTPUT_SEAL_CHANGED')
 print(json.dumps(dict(status='PASS',metrics=summary['metrics'],completed=25,deferred=113,p1Tests=runs[0]['tests'],predecessorTests=sum(r['tests'] or 0 for r in runs[1:3]),boundaryRejections=54,protectedFiles=len(snapshot['protectedFiles']),ownerReview='PENDING')))
def reports(s,v,runs):
 def write(n,lines):(c.OUT/n).write_text('\n'.join(lines)+'\n')
 inv=c.load(c.REL+'/retained-source-inventory.json');available=sum(x['availableRows'] for x in inv);materialized=sum(x['materializedRows'] for x in inv)
 write('DFR_05_P1_IMPLEMENTATION_REPORT.md',['# DFR-05 P1 implementation — RESEARCH_PROVISIONAL',f'Baseline `{c.BASELINE}`. Explicit owner message: “Tôi approve hãy start”, responding to the P1-only approval question. Approval message timestamp remains unknown; recordedAt is receipt-record creation time. This authorizes P1 only; no acceptance of investment judgments, source expansion, valuation inputs or production is inferred.','', '## Implemented contract and source adapters','Implementation: scripts/lib/dfr05_p1.py; builder: scripts/build-dfr05-p1.py; fresh verification/seal: scripts/finalize-dfr05-p1.py. No application, Next.js, database schema or runtime source changes. Python standard library only.','', 'Four deterministic adapters validate original schema/ticker/status, stable occurrence-aware pointers, exact original decimal strings, annual/quarter/YTD/instant metadata, scope, native unit evidence and revision. Unknown dimensions/publication times remain null. Notes preserve full-page pointers and document hashes without duplicating text. CaféF available cells are checked against raw payload bytes/hash/pointer with Decimal, including null/zero; raw values beyond binary precision remain lossless. Combined selections remain unreviewed presentation references, not facts or automatic source promotion.','',f'The24 original source files contain {available} rows/pages. Only {materialized} dependency-relevant cells/pages and explicit FY2022–25 schema/window witnesses are materialized; all original files remain hash-pinned. Adapters support deterministic full traversal, but export does not duplicate unrelated retained history. No source file was deleted or rewritten.','', '## Reused financial and qualification logic',f'Replay rebuilds {s["metrics"]} DFR02 metric objects using its actual verified-input selectors, overlays, sector calculations and standalone VNM bridge. The one explicitly conflicted TCX printed-common node is carried unchanged, value null; no correction is manufactured. Derived ratios retain DFR02 exact fractions and 12dp HALF_EVEN policy; add/subtract use Decimal. Provider crosschecks also match exactly.','', 'DFR03 validate_review is reused; DFR04 topic qualification and closure validators are called for the matching historical assessment families. Four sealed legacy-format judgments lack the newer counterevidence-array format: VNM:BQ-CASH and BID/VIC/VHM:RG-UNC. They pass unchanged M3 band/full-topic validation and exact sealed-object comparison; no counter-reference fields are fabricated. New-format reviews retain the full validator. This compatibility path preserves history and does not authorize creating new legacy assessments.','', '## Explicit dependency graph',f'{s["graphNodes"]} nodes and {s["graphEdges"]} edges connect exact source bindings/raw provider cells, selected extraction cells/pages, verified metrics, qualified context, topics, rubrics and isolated legacy exceptions. Graph IDs and exported order are deterministic; cycles, dangling edges, wrong issuers and new tickers fail closed.','', 'Calculation/support/counterevidence edges propagate source conflicts. Discovery, unreviewed extraction candidates and presentation/provider crosschecks are explicitly non-authoritative. Conflict replay returns a separate status overlay with null points, leaving original metrics and judgments unchanged. Shared document changes affect their actual dependents; a single reviewed pointer does not cause a blanket issuer veto. Conditional earnings/valuation context stays labelled as context, never as a reported financial fact.','', '## Sector routes','BANK (BID), SECURITIES (TCX), TECHNOLOGY (FPT), CONSUMER_DAIRY (VNM), COMPLEX_GROUP (VIC), DEVELOPER (VHM) retain DFR02 research subtypes and explicit economic rules. These are research routing labels, not new approved M3 sectors or formal admission. Bank capital/funding and securities book cash flows cannot silently use industrial FCF. No bands, weights or taxonomy files are changed.','', '## Run / verify','Run `python3 scripts/build-dfr05-p1.py` for deterministic six-pilot exports. Run `python3 scripts/finalize-dfr05-p1.py` for two fresh replays, tests, protected-source checks and an owner-review manifest. Both require the exact baseline and unchanged tracked bytes. Boundary validation requires the repository-supported Node >=22.23.2 <23 from PATH, or an explicit DFR05_NODE_BINARY executable; unsupported versions fail before replay, with no automatic download. Any consumer must verify the manifest, implementation and input hashes before trusting an export; manifest presence alone is insufficient.','', 'No P2, new issuer, external acquisition, new rating, owner valuation assumption, scoring authorization, deployment or ledger operation occurs.'])
 lines=['# P1 financial and research parity — PASS','', '| Issuer | Metric count | All metric objects / provider crosschecks | Completed | Deferred | All23 rubric objects |','|---|---:|---|---:|---:|---|']
 for t,p in v['financialParity']['issuers'].items():lines.append(f'|{t}|{p["metricCount"]}|Exact match|{p["completed"]}|{p["deferred"]}|Exact match|')
 lines+=['',f'Total: **{s["metrics"]} metrics;25 completed provisional assessments;113 deferred;0 new assessments;0 complete issuer scorecards**. Full objects, not only displayed values, match DFR02/DFR04. Deferred classes, topic gaps, resolution paths, points null and bands null are unchanged. Original25 assessment objects are unchanged, including the four explicit legacy-schema rows.','', f'Two fresh same-code pipeline executions produce identical core payload hash `{s["deterministicPayloadHash"]}`. Source projection, metrics, provider crosschecks, graph and qualification replay are included. Only explicitly volatile authorization-record time and receipts are outside this core hash.','', f'Actual tests: P1 {runs[0]["tests"]}/{runs[0]["tests"]}; DFR02 {runs[1]["tests"]}/{runs[1]["tests"]}; closure {runs[2]["tests"]}/{runs[2]["tests"]}, all PASS. Tests cover exact M3 bands/topics, native dimensions, null/zero/missing, Decimal precision, source hashes/pointers, scope/period fixtures, graph locality, unknown provider units, HPG zero-cashflow fixture and six-sector distinctions.','',f'{v["protectedFilesVerified"]} baseline/protected/source/data file fingerprints remain unchanged, including M1–M8, existing research/seals, database/sidecars and active scoring authority. input-pins.json binds source bytes; baseline-snapshot.json binds protected bytes.','', '## Retained exceptions','VIC legacy borrowings342485743 vs identified closing338501032 million VND (difference3984711 million), and VHM148994462 vs146322754 million (difference2671708 million), remain isolated graph exception nodes. Legacy aggregate dependencies do not enter the qualified FH-BS path. No DFR02 correction was made.','TCX printed common numerator differs by1VND; original CONFLICT node/value null is preserved. Unreviewed extraction references do not revoke the separately verified VHM NCI/capital overlay.','', 'See parity-results.json, determinism-results.json, qualification-replay.json and validation-results.json for exact hashes and process receipts.']
 write('DFR_05_P1_PARITY_VALIDATION.md',lines)
 write('DFR_05_P1_BOUNDARY_VALIDATION.md',['# P1 production boundary validation — PASS','', '**54/54 actual probes rejected** for the six P1 dossier objects. Each issuer was tested against formal scorer, ranking root, nested ranking card, decision engine, monthly DCA validation, NAV qualification, ledger transaction builder, formal DI acceptance and formal AI provenance.','', 'Probes import and exercise current repository entry points; they do not replace guards with mocks. Assertions require exceptions and null totalScore/ranking/valuationPerShare. The dossiers retain RESEARCH_PROVISIONAL, productionAdmissible=false and scoringAuthorized=false. No formal input is constructed or authenticated acceptance issued.','', 'A boundary PASS proves rejection of these direct and nested dossier forms. It does not certify arbitrary malicious transformations, authenticated production workflows or the whole application release.','', 'Approved scoring authority verifier PASS:37 artifacts,133 historical files and9 compatibilities; unchanged content hash `8c0880249dc54e2baea0235cc10094f818220db86331442ece3da05085261cc1`. Protected baseline and database byte checks also pass after the actual runtime probes.','', 'boundary-results.json records each rejection and reason; validation-results.json records actual commands, exit codes and output. No ranking, decision, DCA, NAV or ledger write was executed.'])
 write('DFR_05_P1_FINAL_REVIEW.md',['# DFR-05 P1 final review — owner review pending','', 'Implemented P1 only, under the explicit owner approval recorded in owner-authorization.json. Six pilots replay successfully;789 metric objects and provider crosschecks match;25 completed assessments and113 deferred dispositions remain unchanged. Deterministic double replay and all declared tests pass.','', f'Actual verification: {runs[0]["tests"]} P1 tests,25 DFR02 tests,31 closure tests;54 production-boundary rejections; approved authority and protected-byte checks PASS. This is bounded P1 validation, not whole-production acceptance.','', 'Critical P1 engineering issues found:0. Major inherited exceptions retained:2 (VIC/VHM legacy debt definitions); minor inherited conflict retained:1 (TCX common numerator1VND). Four legacy-schema judgments are explicitly preserved compatibility records, not repaired or newly accepted assessments. Existing research/source/valuation and wider production blockers remain open under their existing IDs.','', 'P1 changes no financial/source/assessment history, M1–M8 bands/weights, database, production authority, owner valuation choices or source policy. No completed research is reopened. No new evidence-closure phase is created.','', 'Acceptance requested: review the contract/adapters, dependency semantics, six-pilot parity and rejection evidence. Result acceptance remains PENDING. P1 implementation approval does not constitute acceptance of the25 research judgments or authorize P2.','', '**STOP: do not start P2, process additional issuers, acquire external sources or activate production.** No successor package runs automatically.'])
